class LocalLLMRouter:
    TASK_KEYWORDS = {
        "code": ["function", "class", "code", "implement"],
        "json": ["json", "extract", "structured"]
    }

    CONFIGS = {
        "code": {"temperature": 0.2, "max_tokens": 512},
        "json": {"temperature": 0.1, "max_tokens": 256},
        "chat": {"temperature": 0.7, "max_tokens": 300}
    }

    SYSTEM_PROMPTS = {
        "code": "You are a Python code generator. Return only code.",
        "json": "You are a JSON extractor. Return only valid JSON.",
        "chat": "You are a helpful assistant. Be concise."
    }

    def detect_task(self, prompt: str) -> str:
        text = prompt.lower()
        for task_type in ("code", "json"):
            if any(kw in text for kw in self.TASK_KEYWORDS[task_type]):
                return task_type
        return "chat"

    def get_config(self, task_type: str) -> dict:
        return dict(self.CONFIGS.get(task_type, self.CONFIGS["chat"]))

    def route(self, prompt: str) -> dict:
        task_type = self.detect_task(prompt)
        config = self.get_config(task_type)
        messages = [
            {"role": "system", "content": self.SYSTEM_PROMPTS[task_type]},
            {"role": "user", "content": prompt},
        ]
        return {"task_type": task_type, "config": config, "messages": messages}


# Test it:
router = LocalLLMRouter()
r1 = router.route("Write a function to sort a list")
print(r1["task_type"])
print(r1["config"]["temperature"])

r2 = router.route("Extract JSON from this text")
print(r2["task_type"])
print(len(r2["messages"]))

r3 = router.route("Hello, how are you?")
print(r3["task_type"])
